#!/usr/bin/env node
/**
 * val-init — generate a library's Val agents from the shared templates.
 *
 * Usage (from the library repo root):
 *   npx val-init                      generate .claude/agents + .claude/commands
 *   npx val-init --check              exit 1 if any generated file is stale (CI)
 *   npx val-init --dry-run            print what would change, write nothing
 *   npx val-init --config <path>      config other than val/config.json
 *
 * Reads val/config.json (schema: schema/val.config.schema.json), applies the
 * schema defaults, substitutes {{PLACEHOLDERS}} into every template under
 * templates/agents and templates/commands, and writes the results into the
 * repo's .claude/ directory. Also links <paths.toolsDir> to this package's
 * tools/ so `node val/tools/<tool>.mjs` keeps working.
 *
 * Generated files carry a header saying so. Edit the template or the config,
 * never the output — `--check` in CI catches hand edits.
 */

import {
  readFileSync,
  writeFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  lstatSync,
  readlinkSync,
  symlinkSync,
  unlinkSync,
} from "node:fs";
import { resolve, join, dirname, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const coreRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const corePkg = JSON.parse(readFileSync(join(coreRoot, "package.json"), "utf8"));
const repoRoot = process.cwd();

// ---- args ---------------------------------------------------------------------

const args = process.argv.slice(2);
const flag = (name) => args.includes(name);
const opt = (name, fallback) => {
  const i = args.indexOf(name);
  return i !== -1 && args[i + 1] ? args[i + 1] : fallback;
};
const DRY_RUN = flag("--dry-run");
const CHECK = flag("--check");
const configRel = opt("--config", "val/config.json");
const configPath = resolve(repoRoot, configRel);

if (flag("--help") || flag("-h")) {
  console.log(readFileSync(fileURLToPath(import.meta.url), "utf8").split("\n").slice(1, 18).join("\n").replace(/^ \*\/?\s?/gm, ""));
  process.exit(0);
}

// ---- config + schema defaults -----------------------------------------------

if (!existsSync(configPath)) {
  fail(
    `No config at ${configRel}.\n` +
      `Create it from ${relative(repoRoot, join(coreRoot, "val.config.example.json"))} ` +
      `and set library.name / displayName / figmaFileKey and paths.designSystemSkill.`,
  );
}

const schema = JSON.parse(
  readFileSync(join(coreRoot, "schema", "val.config.schema.json"), "utf8"),
);
const raw = JSON.parse(readFileSync(configPath, "utf8"));
const config = applyDefaults(raw, schema);
validate(config, schema);

// ---- substitutions ------------------------------------------------------------

const { library, paths, typography = {}, pipelines = {} } = config;
const CORE_PKG_DIR = `node_modules/${corePkg.name}`;

const fonts = typography.fonts?.length ? typography.fonts : ["@fontsource/inter"];
const fontList =
  fonts.length === 1
    ? fonts[0]
    : fonts.slice(0, -1).join(", ") + " and " + fonts[fonts.length - 1];

const substitutions = {
  LIBRARY_NAME: library.name,
  LIBRARY_DISPLAY_NAME: library.displayName,
  FIGMA_FILE_KEY: library.figmaFileKey,
  DESIGN_SYSTEM_SKILL_PATH: paths.designSystemSkill,
  REGISTRY_PATH: paths.componentRegistry,
  TOKEN_SOURCE: paths.tokenSource,
  COMPONENT_CSS: paths.componentCss,
  ICON_SPRITE: paths.iconSprite,
  STORIES_DIR: paths.storiesDir.replace(/\/$/, ""),
  COMPONENTS_DIR: paths.componentsDir.replace(/\/$/, ""),
  RUN_OUTPUT_DIR: paths.runOutputDir.replace(/\/$/, ""),
  TOOLS_DIR: paths.toolsDir.replace(/\/$/, ""),
  FIGMA_TOKENS_JSON: paths.figmaTokensJson,
  BUILD_THEME_SCRIPT: paths.buildThemeScript,
  VISUAL_SPECS_SCRIPT: paths.visualSpecsScript,
  COMPONENT_PROCESS_DOC: paths.componentProcessDoc,
  CLAUDE_MD_SECTIONS: paths.claudeMdSections,
  CORE_SKILLS_DIR: `${CORE_PKG_DIR}/skills`,
  FONT_PACKAGES: fontList,
  TYPE_SYSTEM_NOTE:
    typography.systemNote ??
    `use only the faces and text styles ${paths.designSystemSkill} defines`,
  DATA_TYPOGRAPHY_RULE: typography.dataRule ?? "tabular-nums",
  AUDIENCE_NOTE:
    config.audience ??
    `identify the audience/register the page serves (this selects which component families apply).`,
  GENERATED_HEADER:
    `<!-- GENERATED by ${corePkg.name}@${corePkg.version} from ${configRel} ` +
    `(library: ${library.name}). Do not edit — change the template in ` +
    `${CORE_PKG_DIR}/templates/ or the config, then run \`npx val-init\`. -->`,
};

function substitute(text, file) {
  const out = text.replace(/\{\{([A-Z0-9_]+)\}\}/g, (m, key) => {
    if (!(key in substitutions)) {
      fail(`${file}: unknown placeholder {{${key}}} — add it to val-init's substitutions.`);
    }
    return substitutions[key];
  });
  return out;
}

// ---- generate -----------------------------------------------------------------

const wantVal = pipelines.val !== false;
const wantExtract = pipelines.extract !== false;

const jobs = [
  { src: join(coreRoot, "templates", "agents"), dest: join(repoRoot, ".claude", "agents") },
  { src: join(coreRoot, "templates", "commands"), dest: join(repoRoot, ".claude", "commands") },
];

const results = { created: [], updated: [], unchanged: [], skipped: [] };

for (const { src, dest } of jobs) {
  for (const file of readdirSync(src).filter((f) => f.endsWith(".template.md")).sort()) {
    const outName = file.replace(/\.template\.md$/, ".md");
    const isExtract = /^extract/.test(outName);
    if ((isExtract && !wantExtract) || (!isExtract && !wantVal)) {
      results.skipped.push(outName);
      continue;
    }
    const generated = substitute(readFileSync(join(src, file), "utf8"), file);
    const outPath = join(dest, outName);
    const rel = relative(repoRoot, outPath);

    if (existsSync(outPath) && readFileSync(outPath, "utf8") === generated) {
      results.unchanged.push(rel);
      continue;
    }
    (existsSync(outPath) ? results.updated : results.created).push(rel);
    if (!DRY_RUN && !CHECK) {
      mkdirSync(dest, { recursive: true });
      writeFileSync(outPath, generated);
    }
  }
}

// ---- tools symlink ------------------------------------------------------------

const toolsLink = join(repoRoot, paths.toolsDir);
const installedTools = join(repoRoot, CORE_PKG_DIR, "tools");
// Prefer the node_modules path (portable across machines); fall back to
// wherever this script actually lives (e.g. running from a checkout).
const toolsTarget = existsSync(installedTools) ? installedTools : join(coreRoot, "tools");
const linkValue = relative(dirname(toolsLink), toolsTarget).split(sep).join("/");
let toolsNote;

if (existsSync(toolsLink) || isDanglingLink(toolsLink)) {
  const st = lstatSync(toolsLink);
  if (st.isSymbolicLink()) {
    if (readlinkSync(toolsLink) === linkValue) {
      toolsNote = `unchanged  ${paths.toolsDir} -> ${linkValue}`;
    } else {
      toolsNote = `relinked   ${paths.toolsDir} -> ${linkValue}`;
      if (!DRY_RUN && !CHECK) {
        unlinkSync(toolsLink);
        symlinkSync(linkValue, toolsLink, "dir");
      }
    }
  } else {
    toolsNote =
      `SKIPPED    ${paths.toolsDir} is a real directory. The core tools now live in ` +
      `${CORE_PKG_DIR}/tools; remove the directory (git rm -r ${paths.toolsDir}) and ` +
      `re-run val-init to link it.`;
  }
} else {
  toolsNote = `linked     ${paths.toolsDir} -> ${linkValue}`;
  if (!DRY_RUN && !CHECK) {
    mkdirSync(dirname(toolsLink), { recursive: true });
    symlinkSync(linkValue, toolsLink, "dir");
  }
}

// ---- report -------------------------------------------------------------------

const mode = CHECK ? "check" : DRY_RUN ? "dry-run" : "write";
console.log(
  `val-init (${corePkg.name}@${corePkg.version}) — library "${library.name}" — mode: ${mode}\n`,
);
for (const f of results.created) console.log(`  created    ${f}`);
for (const f of results.updated) console.log(`  updated    ${f}`);
for (const f of results.unchanged) console.log(`  unchanged  ${f}`);
for (const f of results.skipped) console.log(`  skipped    ${f} (pipeline disabled in config)`);
console.log(`  ${toolsNote}`);

const changes = results.created.length + results.updated.length;
if (CHECK) {
  if (changes) {
    console.error(
      `\n✗ ${changes} generated file(s) are stale or hand-edited. Run \`npx val-init\` and commit.`,
    );
    process.exit(1);
  }
  console.log("\n✓ generated files are up to date.");
} else if (DRY_RUN) {
  console.log(`\n${changes} file(s) would change. Nothing written.`);
} else {
  console.log(
    `\n✓ ${changes} file(s) written. Review with \`git diff .claude/\`, then stage: ` +
      `git add .claude/ ${paths.toolsDir}`,
  );
}

// ---- helpers ------------------------------------------------------------------

function fail(msg) {
  console.error(`val-init: ${msg}`);
  process.exit(1);
}

function isDanglingLink(p) {
  try {
    return lstatSync(p).isSymbolicLink();
  } catch {
    return false;
  }
}

/** Fill in `default`s from a (simple, nested-object) JSON schema. */
function applyDefaults(value, node) {
  if (node.type !== "object" || !node.properties) return value;
  const out = { ...(value ?? {}) };
  for (const [key, sub] of Object.entries(node.properties)) {
    if (out[key] === undefined) {
      if (sub.default !== undefined) out[key] = structuredClone(sub.default);
      else if (sub.type === "object" && sub.properties) {
        const filled = applyDefaults({}, sub);
        if (Object.keys(filled).length) out[key] = filled;
      }
    } else if (sub.type === "object") {
      out[key] = applyDefaults(out[key], sub);
    }
  }
  return out;
}

/** Minimal validator: required, additionalProperties:false, string patterns/types. */
function validate(value, node, path = "config") {
  const errors = [];
  (function walk(v, n, p) {
    if (n.type === "object") {
      if (typeof v !== "object" || v === null || Array.isArray(v)) {
        errors.push(`${p}: expected object`);
        return;
      }
      for (const req of n.required ?? []) {
        if (v[req] === undefined) errors.push(`${p}.${req}: required`);
      }
      if (n.additionalProperties === false) {
        for (const k of Object.keys(v)) {
          if (!n.properties?.[k]) errors.push(`${p}.${k}: unknown key`);
        }
      }
      for (const [k, sub] of Object.entries(n.properties ?? {})) {
        if (v[k] !== undefined) walk(v[k], sub, `${p}.${k}`);
      }
    } else if (n.type === "string") {
      if (typeof v !== "string") errors.push(`${p}: expected string`);
      else if (n.pattern && !new RegExp(n.pattern).test(v)) {
        errors.push(`${p}: "${v}" does not match ${n.pattern}`);
      }
    } else if (n.type === "boolean") {
      if (typeof v !== "boolean") errors.push(`${p}: expected boolean`);
    } else if (n.type === "array") {
      if (!Array.isArray(v)) errors.push(`${p}: expected array`);
      else if (n.items) v.forEach((item, i) => walk(item, n.items, `${p}[${i}]`));
    }
  })(value, node, path);
  if (errors.length) fail(`invalid ${configRel}:\n  - ` + errors.join("\n  - "));
}
